import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
version = json.loads((root / "version.json").read_text(encoding="utf-8"))
print("- Подписки Happ и Incy импортируют отдельные профили маршрутизации, DNS и источники Geo. Настройки доступны в общем окне маршрутов и через пункт «Маршрутизация подписки» в меню группы.")
print("- Без встроенной маршрутизации подписки её использование выключено. Отключение сохраняет профиль и Geo-источники; ошибочная маршрутизация не мешает импорту серверов.")
print("- Geo-файлы провайдеров загружаются автоматически и хранятся отдельно по источникам. Их категории используются без подмены общей базой.")
print("- Для Xray JSON отображаются протокол и адрес сервера. Полные конфиги сохраняют встроенные балансеры, маршрутизацию и цепочки.")
print("- Hysteria2 и другие протоколы различаются и в JSON с балансерами. Проверяется целостность Geo-кэша и наличие нужных категорий.")
print("- Повреждённая маршрутизация не мешает обновлению серверов. Выбор источника хешей qWDTT сохраняется при обновлении подписки.")
print("- Исправлена привязка VK для хешей qWDTT: вход сохраняет сессию, а доступ API запрашивается при создании недостающих хешей по схеме оригинального клиента. CSQTT использует только ручные хеши.")
print("- Если VK не выдаёт токен через HTTP, окно подтверждения доступа открывается только с согласия пользователя. Общий User-Agent клиента — qThrone с номером версии; подписки сохраняют совместимый префикс Happ/3.0.")
print("- В профилях qWDTT добавлены копирование хешей и отдельная проверка через оригинальный режим клиента с кнопкой СТОП. Проверка не запускает туннель и не меняет активное соединение.")
print("- При обновлении подписок qWDTT/CSQTT сохраняют ID устройства, включая замену сервера и пересоздание списка. Новые профили без ID используют постоянный ID клиента.")
print("- Таблица профилей подстраивает столбцы под ширину окна. Украшение видно и в узком окне; уведомления и прогресс временно заменяют его. Клик по консоли и свободной области сверху снимает выделение профиля.")
print("- После удаления сервиса с VPS конфиг очищается без дополнительного сохранения. Кнопки остановки и сохранения отражают состояние операции и наличие изменений; вкладки VK-релея одинакового размера и закрываются крестиком.")
print()
print(f"Основа: Throne {version['throne_version']}, ветка dev, коммит [{version['throne_commit'][:8]}](https://github.com/throneproj/Throne/commit/{version['throne_commit']}).")
